import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"誠齋易傳","description":"誠齋易傳 - 誠齋易傳","frontmatter":{"title":"誠齋易傳","description":"誠齋易傳 - 誠齋易傳"},"headers":[],"relativePath":"classics/chengzhai/001.md","filePath":"classics/chengzhai/001.md"}'),r={name:"classics/chengzhai/001.md"};function c(i,a,o,p,d,h){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"誠齋易傳",tabindex:"-1"},[l("誠齋易傳 "),e("a",{class:"header-anchor",href:"#誠齋易傳","aria-label":"Permalink to “誠齋易傳”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：誠齋易傳二十卷，宋楊萬里撰。萬里字廷秀，自號誠齋，吉水人。官至寶謨閣學士致仕。韓侂冑召之不起。開禧間聞北伐啟釁，憂憤不食卒。後諡文節。事蹟具宋史本傳。是書大旨本程氏，而多引史傳以證之。初名易外傳，後乃改定今名。宋代書肆曾與程傳並刊以行，謂之程楊易傳。新安陳櫟極非之，以為足以聳文士之觀瞻，而不足以服窮經士之心。然聖人作易，本以「吉、兇、悔、吝」示人事之所從，舍人事而談天道，正後儒說易之病，未可以引史說經病萬里也。理宗嘉熙元年，嘗給札寫藏秘閣。元胡一桂作易本義，附錄纂疏，博採諸家，乃獨不錄此書一字，蓋以其文士輕之。然萬里文章氣節，自足千古，此書亦不可磨滅，至今猶在人間。區區門戶之見，亦何足為萬里輕重歟！乾隆四十二年十月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。誠齋易傳原序",-1),e("p",null,"易者何也？易之為言變也。易者，聖人通變之書也。何謂變？蓋陰陽，太極之變也；五行，陰陽之變也；人與萬物，五行之變也；萬事，人與萬物之變也。古初以迄於今，萬事之變未已也。其作也，一得一失；而其究也，一治一亂。聖人有憂焉，於是幽觀其通而逆紬其圖，易之所以作也。易之為言變也。易者，聖人通變之書也。其窮理盡性，其正心修身，其齊家治國，其處顯，其傃窮，其居常，其遭變，其參天地、合鬼神，萬事之變方來，而變通之道先立。變在彼，變在此，得其道者，蚩可哲，慝可淑，眚可福，危可安，亂可治，致身聖賢而躋世泰和，猶反手也。斯道何道也？中正而已矣。唯中為能中天下之不中，唯正，為能正天下之不正。中正立而萬變通，此二帝三王之聖治，孔子顏、孟之聖學也。後世或以事物之變為不足以攖吾心，舉而捐之於空虛者，是亂天下者也。不然，以為不足以遁吾術，挈而持之以權譎者，是愈亂天下者也。然則學者將欲通變，於何求通？曰道。於何求道？曰中。於何求中？曰正。於何求正？曰易。於何求易？曰心。愚老矣，嘗試與二三子講之，二三子以為愚之言乎非也。愚聞諸先儒，先儒聞諸三聖，三聖聞諸天。淳熙戊申八月二日，廬陵楊萬里序。誠齋易傳原序。",-1)])])}const _=t(r,[["render",c]]);export{u as __pageData,_ as default};
